from copy import deepcopy
import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'geometry-course/textbook'
EX, MODELS = {}, []

def sc(points=(), segments=(), **kw):
    return dict(label=kw.pop('label','Условие'), points=list(points),
                segments=[list(s) for s in segments], **kw)

def tri(a='A',b='B',c='C'): return [[a,b],[b,c],[c,a]]
def eq(a,b,marks=1): return dict(a=a,b=b,marks=marks)
def right(a,o,b): return dict(a=a,vertex=o,b=b)
def arc(o,a,b,marks=0,radius=7): return dict(vertex=o,**{'from':a,'to':b},marks=marks,radius=radius)
def ck(kind,**kw): return dict(type=kind,**kw)
def equal(*pairs): return ck('equalLength',segments=[list(s) for s in pairs])
def perp(a,b,c,d): return ck('perpendicular',segments=[[a,b],[c,d]])
def par(a,b,c,d): return ck('parallel',segments=[[a,b],[c,d]])
def col(*names): return ck('collinear',points=list(names))
def ang(a,o,b,degrees): return ck('angle',points=[a,o,b],degrees=degrees)
def ratio(a,b,c,d,value): return ck('distanceRatio',segments=[[a,b],[c,d]],ratio=value)
def mid(a,b): return [(a[i]+b[i])/2 for i in (0,1)]
def dist(a,b): return math.hypot(a[0]-b[0],a[1]-b[1])
def foot(p,a,b):
    v=[b[i]-a[i] for i in (0,1)];t=sum((p[i]-a[i])*v[i] for i in (0,1))/sum(x*x for x in v)
    return [a[i]+t*v[i] for i in (0,1)]
def meet(a,b,c,d):
    u=[b[i]-a[i] for i in (0,1)];v=[d[i]-c[i] for i in (0,1)]
    den=u[0]*v[1]-u[1]*v[0]
    assert abs(den)>1e-10
    t=((c[0]-a[0])*v[1]-(c[1]-a[1])*v[0])/den
    return [a[i]+t*u[i] for i in (0,1)]
def polar(p,deg,r):
    t=math.radians(deg);return [p[0]+r*math.cos(t),p[1]+r*math.sin(t)]
def fit(points):
    xs,ys=zip(*points.values());s=min(72/(max(xs)-min(xs) or 1),46/(max(ys)-min(ys) or 1))
    return {k:[50+(v[0]-(min(xs)+max(xs))/2)*s,35+(v[1]-(min(ys)+max(ys))/2)*s] for k,v in points.items()}
def row(prompt,text,why,refs): return (prompt,text,why,refs if isinstance(refs,list) else [refs])
def case(v,label,at=0):
    z=deepcopy(v);z.update(label=label,availableFromStep=at);return z
def augment(v,points=(),segments=(),**kw):
    z=deepcopy(v);z['points']=list(dict.fromkeys(z['points']+list(points)));z['segments']+=list(segments);z.update(kw);return z
def add(number,condition,answer,rows,p,initial,views=None,checks=(),cases=(),labels=None,offsets=None,label_only=(),givens=(),notes=()):
    page=79 if number<=270 else 80 if number<=278 else 85
    EX[number]=dict(number=number,printedPages=[page],pdfPages=[page+1],notes=list(notes),parts=[dict(part='single',conditionSummary=condition,answer=answer,
        steps=[r[1] for r in rows],sourceVerified=True,mathVerified=True,
        visual=dict(initial='Собственный чертёж условия; вычисления находятся рядом.',stepChanges=['Построения раскрываются на нужном шаге.'],cases=[c['label'] for c in cases]))])
    seq=views or [initial]*len(rows);assert len(seq)==len(rows),(number,len(seq),len(rows))
    vv={'neutral':deepcopy(initial)}
    for i,v in enumerate(seq,1):vv[f'step-{i}']=deepcopy(v);vv[f'step-{i}']['label']=f'Шаг {i}'
    for i,v in enumerate(cases,1):vv[f'case-{i}']=deepcopy(v)
    pp=fit(p)
    m=dict(points={k:[round(v[0],9),round(v[1],9),0] for k,v in pp.items()},edges=[],planar=True,bounds=[0,0,100,70],views=vv,checks=list(checks),
       description='Отдельный чертёж этой задачи. Данные условия видны сразу; дополнительные линии раскрываются по шагам. Вычисления остаются рядом.')
    m['labelOffsets']={k:[-3 if v[0]<48 else 3,5 if v[1]>=35 else -5] for k,v in pp.items() if not k.startswith('_')}
    if offsets:m['labelOffsets'].update(offsets)
    if labels:m['labels']=labels
    if label_only:m['labelOnly']=list(label_only)
    MODELS.append(dict(chapter=4,collection='main',number=number,part='single',model=m,
        didactics=dict(steps=[dict(prompt=r[0],justification=r[2],theoryPoints=r[3]) for r in rows]),statementGivens=list(givens)))

