# 266. Three apex-angle cases share one general proof, with separate scenes.
def iso_heights(prefix,height):
    p={prefix+'A':(0,height),prefix+'B':(-1,0),prefix+'C':(1,0)}
    p[prefix+'H']=foot(p[prefix+'B'],p[prefix+'A'],p[prefix+'C'])
    p[prefix+'K']=foot(p[prefix+'C'],p[prefix+'A'],p[prefix+'B'])
    a,b,c,h,k=[prefix+x for x in 'ABCHK']
    v=sc([a,b,c],tri(a,b,c),equalSegments=[eq(a,b),eq(a,c)])
    w=augment(v,[h,k],[[b,h],[c,k],[a,h],[a,k]],rightAngles=[right(b,h,c),right(c,k,b)])
    return p,v,w,[equal((a,b),(a,c)),equal((b,h),(c,k)),perp(b,h,a,c),perp(c,k,a,b)]
