p={'A':(-1,0),'C':(1,0),'B':(0,math.tan(math.radians(34)))};p['H']=foot(p['A'],p['B'],p['C']);length=dist(p['A'],p['B']);t=length/(length+2);p['F']=[p['B'][i]+t*(p['C'][i]-p['B'][i]) for i in (0,1)]
v=sc(list(p),tri()+[['A','F'],['A','H'],['H','B']],rightAngles=[right('A','H','C')],equalSegments=[eq('A','B'),eq('B','C')],angleArcs=[arc('A','B','F',1),arc('A','F','C',1)])
add(270,'В равнобедренном треугольнике ABC с основанием AC проведены биссектриса AF и высота AH. Найдите углы треугольника AHF, если ∠B=112°.','∠AHF=90°; ∠HAF=39°; ∠AFH=51°.',[
 row('Чему равны углы при основании?','∠A=∠C=(180°−112°):2=34°.','Свойство равнобедренного треугольника и сумма углов.',[18,31]),
 row('Какой угол отсекает биссектриса?','∠CAF=34°:2=17°. Высота AH встречает продолжение BC за B, поскольку угол B тупой.','Биссектриса и положение высоты.',17),
 row('Как найти угол HAC?','В прямоугольном △AHC угол C равен 34°, поэтому ∠HAC=90°−34°=56°.','Сумма острых углов.',35),
 row('Как найти два оставшихся угла △AHF?','∠HAF=56°−17°=39°. Затем ∠AFH=90°−39°=51°; угол H —прямой.','Сложение углов и сумма углов прямоугольного треугольника.',[9,35])],p,v,checks=[equal(('A','B'),('B','C')),ang('A','B','C',112),perp('A','H','B','C'),ang('B','A','F',17),ang('H','A','F',39),ang('A','F','H',51)],offsets={'F':[3,6]},givens=['AB=BC','∠B=112°','AF —биссектриса','AH⊥BC'])

# 271. The common hypotenuse gives the required angle halves.
