add(274,'Докажите, что △ABC=△A₁B₁C₁, если ∠A=∠A₁, ∠B=∠B₁ и BH=B₁H₁, где BH и B₁H₁ —высоты этих треугольников.','△ABC=△A₁B₁C₁.',[
 row('Какое равенство сторон достаточно получить?','Достаточно доказать AB=A₁B₁: тогда равная сторона и два данных прилежащих угла дадут равенство треугольников.','Второй признак равенства.',19),
 row('Что происходит при прямом угле A?','Тогда H=A и H₁=A₁, поэтому AB=BH=B₁H₁=A₁B₁. Этот случай уже решён.','Высота совпадает с перпендикулярной стороной.',17),
 row('Как сравнить маленькие треугольники в остальных случаях?','В прямоугольных △ABH и △A₁B₁H₁ равны катеты BH,B₁H₁. Противолежащие им острые углы равны: это ∠A,∠A₁ при острых A,A₁ или 180°−∠A,180°−∠A₁ при тупых.','Смежные углы и положение основания высоты.',[11,17]),
 row('Как закончить доказательство?','По признаку из задачи 273 маленькие прямоугольные треугольники равны, откуда AB=A₁B₁. Затем по стороне AB и прилежащим углам A,B равны исходные треугольники.','Признак по катету и противолежащему углу; второй признак.',[36,19])],p,v,[v,rv,v,v],checks=[equal(('B','H'),('B1','H1')),equal(('A','B'),('A1','B1')),perp('B','H','A','C'),perp('oB','oH','oA','oC'),ang('rB','rA','rC',90)],cases=[case(ov,'Тупой угол A',3),case(rv,'Прямой угол A',2)],labels={**{x+'1':x+'₁' for x in 'ABCH'},**{f'o{x}':x for x in 'ABCH'},**{f'r{x}':x for x in 'ABC'}},givens=['∠A=∠A₁','∠B=∠B₁','BH=B₁H₁'])

