u=augment(v,['H'],[['D','H']],rightAngles=[right('D','H','A')])
w=augment(u,rightAngles=[right('D','H','A'),right('A','D','C')])
add(280,'В равностороннем треугольнике ABC проведена биссектриса AD. Расстояние от D до прямой AC равно 6 см. Найдите расстояние от A до прямой BC.','12 см.',[
 row('Какой отрезок равен 6 см?','Опустим DH⊥AC. По условию DH=6 см. Угол A равностороннего треугольника равен 60°, поэтому ∠DAH=30°.','Расстояние до прямой; биссектриса.',[37,17,31]),
 row('Как найти AD?','В прямоугольном △ADH катет DH лежит против 30°. Поэтому AD=2DH=12 см.','Свойство катета против 30°.',35),
 row('Почему AD —расстояние до BC?','В равностороннем, а значит равнобедренном треугольнике биссектриса AD является высотой. Поэтому расстояние от A до BC равно AD=12 см.','Биссектриса равнобедренного треугольника и расстояние до прямой.',[18,37])],p,v,[u,u,w],checks=[equal(('A','B'),('B','C'),('A','C')),perp('D','H','A','C'),perp('A','D','B','C'),ang('D','A','H',30),ratio('A','D','D','H',2)],givens=['AB=BC=CA','AD —биссектриса','DH⊥AC','DH=6 см'])

