add(281,'Сумма гипотенузы CE и катета CD прямоугольного треугольника CDE равна 31 см, а их разность 3 см. Найдите расстояние от C до прямой DE.','14 см.',[
 row('Где расположен прямой угол?','CE —гипотенуза, значит прямой угол находится при D. Поэтому CD⊥DE и искомое расстояние равно CD.','Гипотенуза и определение расстояния до прямой.',[32,37]),
 row('Как найти CD?','Гипотенуза длиннее катета: CE−CD=3, CE+CD=31. Вычитая, получаем 2CD=28, откуда CD=14 см.','Сложение и вычитание длин.',7),
 row('Как проверить результат?','CE=17 см;17+14=31 и 17−14=3. Расстояние от C до DE равно 14 см.','Проверка обоих условий.',7)],p,v,checks=[ang('C','D','E',90),ratio('C','E','C','D',17/14)],givens=['CE —гипотенуза','CE+CD=31 см','CE−CD=3 см'])

# 282. Midpoint of the base is on the apex bisector.
p={'A':(0,2),'B':(-1.4,0),'C':(1.4,0),'D':(0,0)};p['E']=foot(p['D'],p['A'],p['B']);p['F']=foot(p['D'],p['A'],p['C'])
