p={'A':(-1.4,0),'B':(1.4,0),'C':(0,2),'M':(0,0)};p['H']=foot(p['M'],p['A'],p['C']);p['K']=foot(p['M'],p['B'],p['C'])
v=sc(list(p),tri()+[['M','H'],['M','K']],rightAngles=[right('M','H','A'),right('M','K','B')],equalSegments=[eq('A','C'),eq('B','C'),eq('M','H',2),eq('M','K',2)])
