add(287,'Докажите, что все точки плоскости, лежащие по одну сторону от данной прямой и равноудалённые от неё, лежат на прямой, параллельной данной.','Все такие точки лежат на одной параллельной прямой.',[
 row('Как зафиксировать нужную параллельную прямую?','Выберем одну такую точку P. Пусть PH⊥a и PH=d. Через P проведём прямую b∥a.','Параллельная через данную точку.',28),
 row('Как проверить любую другую точку Q?','Пусть Q лежит с той же стороны от a и QK⊥a, QK=d. Перпендикуляр через K пересекает b в R.','Перпендикуляр к двум параллельным прямым.',[29,37]),
 row('Почему R совпадает с Q?','По уже доказанной теореме о расстояниях между параллельными прямыми RK=PH=d. Точки Q и R лежат на одном луче от K и имеют одинаковое расстояние d от K, значит Q=R.','Прямое свойство параллельных прямых; единственность откладывания отрезка.',[37,7]),
 row('Как закончить общее доказательство?','Любая допустимая точка Q принадлежит b. Следовательно, все такие точки лежат на прямой b, параллельной a.','Выбранная точка Q была произвольной.',27)],p,v,[w,w,w,w],checks=[par('_L','_R','_U','_V'),equal(('P','H'),('Q','K')),perp('P','H','_L','_R'),perp('Q','K','_L','_R')],label_only=['a','b'],givens=['P и Q по одну сторону от a','PH=QK=d','PH⊥a','QK⊥a'],notes=['В построении R=Q; отдельные совпадающие метки на рисунке не дублируются.'])

